styles:
:root{ --gold:#C19A3D; --gold-dark:#9A7B2D; --ink:#141414; --muted:#6d675c; --ivory:#faf7f1; --card:#ffffff; --line:#ece4d2; }
*{ margin:0; padding:0; box-sizing:border-box; }
body{ font-family:'Inter',sans-serif; color:var(--ink); background:linear-gradient(180deg,#fdfbf7 0%, var(--ivory) 55%, #f3ecdd 100%); min-height:100vh; }
.wrap{ max-width:560px; margin:0 auto; padding:0 20px 64px; }
header.top{ display:flex; justify-content:space-between; align-items:center; padding:20px 0 6px; }
.wordmark{ font-family:'Playfair Display',serif; font-weight:700; letter-spacing:.35em; font-size:17px; }
.wordmark small{ display:block; letter-spacing:.55em; font-size:9px; font-weight:600; color:var(--gold-dark); margin-top:2px; }
.eyebrow{ font-size:12px; letter-spacing:.22em; text-transform:uppercase; color:var(--gold-dark); font-weight:600; margin-bottom:12px; }
h1{ font-family:'Playfair Display',serif; font-size:clamp(32px,7.4vw,44px); line-height:1.12; font-weight:600; }
h1 em{ color:var(--gold-dark); font-style:italic; }
p.lede{ color:var(--muted); font-size:16px; line-height:1.6; margin:14px 0 26px; }
p.note{ color:var(--muted); font-size:13.5px; line-height:1.55; margin-top:14px; }
.cta{ display:block; width:100%; background:var(--gold); color:#fff; border:none; font:600 16px 'Inter',sans-serif; padding:16px 30px; border-radius:999px; cursor:pointer; letter-spacing:.03em; box-shadow:0 10px 24px rgba(193,154,61,.35); text-align:center; text-decoration:none; }
.cta:hover{ background:var(--gold-dark); }
.cardbox{ background:var(--card); border:1px solid var(--line); border-radius:18px; padding:24px 22px; box-shadow:0 6px 18px rgba(60,48,20,.05); margin:18px 0; }
.cardbox h3{ font-family:'Playfair Display',serif; font-size:20px; font-weight:600; margin-bottom:8px; }
.cardbox p{ color:var(--muted); font-size:14.5px; line-height:1.6; }
.planrow{ display:flex; gap:12px; padding:11px 0; border-top:1px solid var(--line); font-size:14.5px; }
.planrow:first-of-type{ border-top:none; }
.planrow .k{ flex:0 0 108px; color:var(--gold-dark); font-weight:600; font-size:12.5px; letter-spacing:.06em; text-transform:uppercase; padding-top:2px; }
.planrow .v{ line-height:1.5; }
.check{ width:64px; height:64px; border-radius:50%; background:#fff8e8; border:1.5px solid var(--gold); color:var(--gold-dark); font-size:30px; line-height:64px; text-align:center; margin:26px 0 18px; }
footer{ text-align:center; color:var(--muted); font-size:12.5px; padding:30px 0 6px; }

